/// <summary>
/// designed from AVA
/// </summary>
void init()
{
    next init();
    if (this.args().dataset() == tableNum(KCS_KBVBuildingProjectTable))
    {
        KCS_KBVBuildingProjectTable         buildingProjectTable = this.args().record();
        FormDataSource                      cityDS = this.dataSource('LogisticsAddressCity');
        cityDS.query().dataSourceTable(tableNum(LogisticsAddressCity)).addRange(fieldNum(LogisticsAddressCity,CountryRegionId)).value(buildingProjectTable.AddressCountryRegionId);
    }


}
